.fuse-button {
  --fb-ink: #f5f5f5;
  --fb-bg: #27272a;
  --fb-fuse: #f5a524;
  --fb-fuse-h: 1.5px;
  --fb-radius: 22px;
  --fb-fade: 200ms;
  --fb-press: 0.97;
  --fb-h: 44px;
  --fb-fs: 14px;
  --fb-icon: 15px;
  --fb-px: 20px;
  --fb-ease-out: cubic-bezier(0.23, 1, 0.32, 1);

  position: relative;
  display: inline-grid;
  grid-template-columns: minmax(0, 1fr);
  height: var(--fb-h);
  border-radius: var(--fb-radius);
  background: var(--fb-bg);
  color: var(--fb-ink);
  font-family: inherit;
  font-size: var(--fb-fs);
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0.01em;
  overflow: hidden;
  isolation: isolate;
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  transition: transform 160ms var(--fb-ease-out);
}

.fuse-button[data-pressed] {
  transform: scale(var(--fb-press));
}

.fuse-button:has(:focus-visible) {
  outline: 2px solid color-mix(in srgb, var(--fb-ink) 60%, transparent);
  outline-offset: 3px;
}

.fuse-button__idle:focus-visible,
.fuse-button__undo:focus-visible {
  outline: none;
}

@supports not selector(:has(a)) {
  .fuse-button__idle:focus-visible,
  .fuse-button__undo:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--fb-ink) 60%, transparent);
    outline-offset: -3px;
  }
}

.fuse-button__face {
  position: relative;
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  height: 100%;
  min-width: 0;
  margin: 0;
  padding: 0 var(--fb-px);
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  white-space: nowrap;
  cursor: pointer;
  opacity: 0;
  filter: blur(2px);
  visibility: hidden;
  transition:
    opacity var(--fb-fade) ease,
    filter var(--fb-fade) ease,
    visibility 0s linear var(--fb-fade),
    background-color 160ms ease;
}

.fuse-button[data-phase='idle'] .fuse-button__idle,
.fuse-button[data-phase='armed'] .fuse-button__undo,
.fuse-button[data-phase='settled'] .fuse-button__settled {
  opacity: 1;
  filter: blur(0);
  visibility: visible;
  transition-delay: 0s;
}

.fuse-button[data-instant] .fuse-button__face {
  transition-duration: 0s;
}

.fuse-button__idle:disabled,
.fuse-button__settled {
  cursor: default;
}

.fuse-button[data-phase='idle']:has(.fuse-button__idle:disabled) {
  opacity: 0.55;
}

.fuse-button__icon {
  display: inline-flex;
  width: var(--fb-icon);
  height: var(--fb-icon);
}

.fuse-button__icon svg {
  width: 100%;
  height: 100%;
}

.fuse-button__icon--undo {
  transform: rotate(-70deg);
  transition: transform var(--fb-fade) var(--fb-ease-out);
}

.fuse-button[data-phase='armed'] .fuse-button__icon--undo {
  transform: rotate(0deg);
}

.fuse-button__fuse {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: var(--fb-fuse-h);
  background: var(--fb-fuse);
  box-shadow: 0 0 6px color-mix(in srgb, var(--fb-fuse) 55%, transparent);
  transform-origin: left center;
  pointer-events: none;
}

.fuse-button[data-fuse='top'] .fuse-button__fuse {
  bottom: auto;
  top: 0;
}

.fuse-button__rim {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
  opacity: 0;
  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--fb-fuse) 60%, transparent));
  transition: opacity var(--fb-fade) ease;
}

.fuse-button[data-phase='armed'] .fuse-button__rim {
  opacity: 1;
}

.fuse-button[data-instant] .fuse-button__rim {
  transition-duration: 0s;
}

.fuse-button__rim rect {
  x: calc(var(--fb-fuse-h) / 2);
  y: calc(var(--fb-fuse-h) / 2);
  width: calc(100% - var(--fb-fuse-h));
  height: calc(100% - var(--fb-fuse-h));
  rx: max(0px, calc(var(--fb-radius) - var(--fb-fuse-h) / 2));
  fill: none;
  stroke: var(--fb-fuse);
  stroke-width: var(--fb-fuse-h);
  stroke-linecap: round;
  stroke-dasharray: 1;
}

.fuse-button__status {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (hover: hover) and (pointer: fine) {
  .fuse-button__idle:not(:disabled):hover,
  .fuse-button__undo:hover {
    background: color-mix(in srgb, var(--fb-ink) 7%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .fuse-button[data-pressed] {
    transform: none;
  }

  .fuse-button .fuse-button__face {
    filter: none;
    transition:
      opacity var(--fb-fade) ease,
      visibility 0s linear var(--fb-fade);
  }

  .fuse-button .fuse-button__icon--undo {
    transform: none;
    transition: none;
  }
}

@media (prefers-contrast: more) {
  .fuse-button {
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fb-ink) 40%, transparent);
  }
}

@media (forced-colors: active) {
  .fuse-button__fuse {
    background: Highlight;
  }

  .fuse-button__rim rect {
    stroke: Highlight;
  }
}

import { Show, createEffect, createMemo, createSignal, createUniqueId, onSettled } from 'solid-js';
import type { JSX } from '@solidjs/web';
import { Archive02Icon, Tick02Icon, Undo02Icon } from '@hugeicons/core-free-icons';

import './FuseButton.css';

export type FusePosition = 'outline' | 'bottom' | 'top';
export type FuseCommitOn = 'press' | 'fuseEnd';
export type FuseSettle = 'reset' | 'stay';
export type FusePhase = 'idle' | 'armed' | 'settled';
export type FuseSize = 'sm' | 'md' | 'lg';

export interface FuseButtonProps {
  label?: string;
  undoLabel?: string;
  doneLabel?: string;
  icon?: JSX.Element;
  color?: string;
  background?: string;
  fuseColor?: string;
  size?: FuseSize;
  radius?: number;
  undoWindow?: number;
  fuse?: FusePosition;
  fuseThickness?: number;
  crossfadeMs?: number;
  commitOn?: FuseCommitOn;
  pauseOnHover?: boolean;
  settle?: FuseSettle;
  disabled?: boolean;
  onCommit?: (reason: FuseCommitOn) => void;
  onUndo?: () => void;
  onFuseEnd?: () => void;
  onPhaseChange?: (phase: FusePhase) => void;
  className?: string;
  type?: 'button' | 'submit' | 'reset';
}

type Settings = {
  undoWindow: number;
  fuse: FusePosition;
  commitOn: FuseCommitOn;
  pauseOnHover: boolean;
  settle: FuseSettle;
  disabled: boolean;
  onCommit?: (reason: FuseCommitOn) => void;
  onUndo?: () => void;
  onFuseEnd?: () => void;
  onPhaseChange?: (phase: FusePhase) => void;
};

type IconSvgElement = readonly (readonly [string, { readonly [key: string]: string | number }])[];

const LINE: Keyframe[] = [{ transform: 'scaleX(1)' }, { transform: 'scaleX(0)' }];
const OUTLINE: Keyframe[] = [{ strokeDashoffset: 0 }, { strokeDashoffset: -1 }];
const SIZES: Record<FuseSize, { height: number; font: number; icon: number; px: number }> = {
  sm: { height: 36, font: 13, icon: 14, px: 16 },
  md: { height: 44, font: 14, icon: 15, px: 20 },
  lg: { height: 52, font: 15, icon: 17, px: 24 }
};

const escapeAttr = (value: string | number) => String(value).replace(/&/g, '&amp;').replace(/"/g, '&quot;');

const iconMarkup = (icon: IconSvgElement, strokeWidth: number) =>
  icon
    .map(([tag, attrs]) => {
      const parts = Object.entries(attrs)
        .filter(([key]) => key !== 'key')
        .map(([key, value]) => {
          const name = key.replace(/[A-Z]/g, char => `-${char.toLowerCase()}`);
          return `${name}="${escapeAttr(name === 'stroke-width' ? strokeWidth : value)}"`;
        });
      return `<${tag} ${parts.join(' ')}></${tag}>`;
    })
    .join('');

function Icon(props: { icon: IconSvgElement; size: number; strokeWidth: number }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={props.size}
      height={props.size}
      viewBox="0 0 24 24"
      fill="none"
      color="currentColor"
      innerHTML={iconMarkup(props.icon, props.strokeWidth)}
    />
  );
}

export default function FuseButton(props: FuseButtonProps) {
  let rootEl: HTMLSpanElement | undefined;
  let idleEl: HTMLButtonElement | undefined;
  let undoEl: HTMLButtonElement | undefined;
  let lineEl: HTMLElement | undefined;
  let rimEl: SVGRectElement | undefined;
  let anim: Animation | null = null;
  let current!: Settings;
  let phaseNow: FusePhase = 'idle';
  let windowMs = 4000;
  let lastInput: 'pointer' | 'keyboard' = 'pointer';
  const pause = { hover: false, hidden: false, canHoverPause: false };

  const [phase, setPhase] = createSignal<FusePhase>('idle');
  const [instant, setInstant] = createSignal(false);
  const statusId = createUniqueId();

  const settings = createMemo<Settings>(() => ({
    undoWindow: props.undoWindow ?? 4000,
    fuse: props.fuse ?? 'outline',
    commitOn: props.commitOn ?? 'press',
    pauseOnHover: props.pauseOnHover ?? true,
    settle: props.settle ?? 'reset',
    disabled: props.disabled ?? false,
    onCommit: props.onCommit,
    onUndo: props.onUndo,
    onFuseEnd: props.onFuseEnd,
    onPhaseChange: props.onPhaseChange
  }));

  const fuse = () => props.fuse ?? 'outline';
  const preset = () => SIZES[props.size ?? 'md'] || SIZES.md;

  const go = (next: FusePhase) => {
    setInstant(lastInput === 'keyboard');
    setPhase(next);
    phaseNow = next;
    current.onPhaseChange?.(next);
  };

  const syncPlayState = () => {
    const a = anim;
    if (!a) return;
    const { hover, hidden } = pause;
    if (hover || hidden) {
      if (a.playState === 'running') a.pause();
    } else if (a.playState === 'paused') {
      a.play();
    }
  };

  const light = (from = 0) => {
    const outline = current.fuse === 'outline';
    const el = outline ? rimEl : lineEl;
    if (!el) return;
    anim?.cancel();
    const a = el.animate(outline ? OUTLINE : LINE, {
      duration: windowMs,
      easing: 'linear',
      fill: 'forwards'
    });
    if (from) a.currentTime = from;
    a.onfinish = () => {
      const l = current;
      l.onFuseEnd?.();
      if (l.commitOn === 'fuseEnd') l.onCommit?.('fuseEnd');
      lastInput = 'pointer';
      go(l.settle === 'stay' ? 'settled' : 'idle');
    };
    anim = a;
    syncPlayState();
  };

  const arm = () => {
    if (current.disabled || phaseNow !== 'idle') return;
    windowMs = current.undoWindow;
    light();
    pause.canHoverPause = false;
    pause.hover = false;
    if (current.commitOn === 'press') current.onCommit?.('press');
    go('armed');
  };

  const undo = () => {
    if (phaseNow !== 'armed') return;
    const a = anim;
    if (a) {
      a.onfinish = null;
      a.pause();
    }
    current.onUndo?.();
    go('idle');
  };

  createEffect(settings, value => {
    const prevFuse = current?.fuse;
    current = value;
    if (prevFuse !== undefined && prevFuse !== value.fuse && anim && phaseNow === 'armed') {
      light(Number(anim.currentTime) || 0);
    }
    if (!value.pauseOnHover) {
      pause.hover = false;
      syncPlayState();
    }
  });

  createEffect(phase, next => {
    const inside = rootEl?.contains(document.activeElement);
    if (next === 'armed') undoEl?.focus({ preventScroll: true });
    else if (inside) (next === 'idle' ? idleEl : rootEl)?.focus({ preventScroll: true });
  });

  onSettled(() => {
    current = settings();
    const onVisibility = () => {
      pause.hidden = document.hidden;
      syncPlayState();
    };
    document.addEventListener('visibilitychange', onVisibility);
    return () => {
      document.removeEventListener('visibilitychange', onVisibility);
      anim?.cancel();
    };
  });

  const handlePointerDown = (e: PointerEvent) => {
    lastInput = 'pointer';
    const pressable = phaseNow === 'armed' || (phaseNow === 'idle' && !current.disabled);
    if (e.button === 0 && pressable && rootEl) rootEl.dataset.pressed = '';
  };
  const release = () => {
    if (rootEl) delete rootEl.dataset.pressed;
  };
  const handlePointerEnter = (e: PointerEvent) => {
    if (current.pauseOnHover && e.pointerType === 'mouse' && pause.canHoverPause) {
      pause.hover = true;
      syncPlayState();
    }
  };
  const handlePointerLeave = (e: PointerEvent) => {
    release();
    if (e.pointerType !== 'mouse') return;
    pause.canHoverPause = true;
    pause.hover = false;
    syncPlayState();
  };
  const handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') lastInput = 'keyboard';
    if (e.key === 'Escape' && phaseNow === 'armed') {
      e.preventDefault();
      lastInput = 'keyboard';
      undo();
    }
  };

  const actionIcon = () => props.icon ?? <Icon icon={Archive02Icon} size={preset().icon} strokeWidth={1.8} />;

  return (
    <span
      ref={el => (rootEl = el)}
      tabindex={-1}
      class={['fuse-button', props.className]}
      data-phase={phase()}
      data-fuse={fuse()}
      data-instant={instant() ? '' : undefined}
      aria-disabled={phase() === 'settled' ? 'true' : undefined}
      style={{
        '--fb-ink': props.color ?? '#f5f5f5',
        '--fb-bg': props.background ?? '#27272a',
        '--fb-fuse': props.fuseColor ?? '#f5a524',
        '--fb-fuse-h': `${props.fuseThickness ?? 1.5}px`,
        '--fb-radius': `${props.radius ?? 22}px`,
        '--fb-fade': `${props.crossfadeMs ?? 200}ms`,
        '--fb-h': `${preset().height}px`,
        '--fb-fs': `${preset().font}px`,
        '--fb-icon': `${preset().icon}px`,
        '--fb-px': `${preset().px}px`
      }}
      onPointerDown={handlePointerDown}
      onPointerUp={release}
      onPointerCancel={release}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      onKeyDown={handleKeyDown}
    >
      <button
        ref={el => (idleEl = el)}
        type={props.type ?? 'button'}
        class="fuse-button__face fuse-button__idle"
        disabled={props.disabled ?? false}
        inert={phase() !== 'idle'}
        onClick={arm}
      >
        <span class="fuse-button__icon" aria-hidden="true">
          {actionIcon()}
        </span>
        {props.label ?? 'Archive'}
      </button>
      <button
        ref={el => (undoEl = el)}
        type="button"
        class="fuse-button__face fuse-button__undo"
        aria-describedby={statusId}
        aria-keyshortcuts="Escape"
        inert={phase() !== 'armed'}
        onClick={undo}
      >
        <span class="fuse-button__icon fuse-button__icon--undo" aria-hidden="true">
          <Icon icon={Undo02Icon} size={preset().icon} strokeWidth={2} />
        </span>
        {props.undoLabel ?? 'Undo'}
        <Show when={fuse() !== 'outline'}>
          <i ref={el => (lineEl = el)} class="fuse-button__fuse" aria-hidden="true" />
        </Show>
      </button>
      <span class="fuse-button__face fuse-button__settled" inert={phase() !== 'settled'}>
        <span class="fuse-button__icon" aria-hidden="true">
          <Icon icon={Tick02Icon} size={preset().icon} strokeWidth={2.2} />
        </span>
        {props.doneLabel ?? 'Archived'}
      </span>
      <Show when={fuse() === 'outline'}>
        <svg class="fuse-button__rim" aria-hidden="true">
          <rect ref={el => (rimEl = el)} pathLength="1" />
        </svg>
      </Show>
      <span class="fuse-button__status" id={statusId} role="status" aria-live="polite">
        {phase() === 'idle' ? '' : (props.doneLabel ?? 'Archived')}
      </span>
    </span>
  );
}
